script:
set r to open3D "box" dimensions {3, 4, 5} field (createarray 60)
try
	extract3D r start {1, 1, 1} length {3, 4, 5}
	extract3D r start {2, 3, 4} length {1, 1, 1}
	extract3D r start {1, 2, 3} length {2, 2, 2}
	extract3D r start {3, 1, 1} length {1, 4, 1}
	extract3D r start {1, 1, 2} length {3, 1, 4}
on error errorText number n
	close3D r
	error errorText number n
end try
close3D r
